//! Called from the code generated by the derive macro. Not public API: do not use directly; not
//! covered by semver guarantees.

use crate::{FromEnvError, FromEnvErrors, parser::Parser};

pub fn required<T>(path: &str, var: &str, parser: &impl Parser<T>) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => Err(FromEnvError::MissingVar {
            path: path.to_string(),
            var: var.to_string(),
        }),
    }
}

pub fn optional<T>(
    path: &str,
    var: &str,
    parser: &impl Parser<T>,
) -> Result<Option<T>, FromEnvError> {
    // No silent fallback to the None case if parsing fails
    read(path, var)?
        .map(|value| parse(path, var, value, parser))
        .transpose()
}

pub fn with_default<T>(
    path: &str,
    var: &str,
    default: &str,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => parser
            .parse(default)
            .map_err(|error| FromEnvError::InvalidDefault {
                path: path.to_string(),
                var: var.to_string(),
                default: default.to_string(),
                source: error,
            }),
    }
}

/// Like [`with_default`], but the default is a typed value. It is only computed when the variable
/// is unset and is not passed through the parser.
pub fn with_default_value<T>(
    path: &str,
    var: &str,
    default: impl FnOnce() -> T,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    match read(path, var)? {
        Some(value) => parse(path, var, value, parser),
        None => Ok(default()),
    }
}

fn read(path: &str, var: &str) -> Result<Option<String>, FromEnvError> {
    match std::env::var(var) {
        Ok(value) => Ok(Some(value)),
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(ref error @ std::env::VarError::NotUnicode(ref malformed_value)) => {
            Err(FromEnvError::ParseError {
                path: path.to_string(),
                var: var.to_string(),
                value: malformed_value.to_string_lossy().to_string(),
                source: error.clone().into(),
            })
        }
    }
}

pub fn parse<T>(
    path: &str,
    var: &str,
    value: String,
    parser: &impl Parser<T>,
) -> Result<T, FromEnvError> {
    parser
        .parse(&value)
        .map_err(|error| FromEnvError::ParseError {
            path: path.to_string(),
            var: var.to_string(),
            value,
            source: error,
        })
}

#[derive(Default)]
pub struct ErrorCollector(Vec<FromEnvError>);

impl ErrorCollector {
    pub fn new() -> Self {
        Self(Vec::new())
    }

    pub fn handle<T>(&mut self, result: Result<T, FromEnvError>) -> Option<T> {
        match result {
            Ok(value) => Some(value),
            Err(error) => {
                self.0.push(error);
                None
            }
        }
    }

    pub fn handle_nested<T>(
        &mut self,
        prefix: &str,
        result: Result<T, FromEnvErrors>,
    ) -> Option<T> {
        match result {
            Ok(value) => Some(value),
            Err(FromEnvErrors(errors)) => {
                self.0.extend(errors.into_iter().map(|mut error| {
                    match &mut error {
                        FromEnvError::MissingVar { path, .. }
                        | FromEnvError::ParseError { path, .. }
                        | FromEnvError::InvalidDefault { path, .. } => {
                            *path = format!("{prefix}.{path}");
                        }
                    }
                    error
                }));
                None
            }
        }
    }

    pub fn finish(self) -> FromEnvErrors {
        FromEnvErrors(self.0)
    }
}

/// The total length of `parts`, used as the array length for [`concat`].
pub const fn concat_len(parts: &[&str]) -> usize {
    let mut len = 0;
    let mut i = 0;
    while i < parts.len() {
        len += parts[i].len();
        i += 1;
    }
    len
}

/// Concatenates `parts` at compile time. `N` must be [`concat_len`] of `parts`.
pub const fn concat<const N: usize>(parts: &[&str]) -> [u8; N] {
    let mut out = [0; N];
    let mut pos = 0;
    let mut i = 0;
    while i < parts.len() {
        let bytes = parts[i].as_bytes();
        let mut j = 0;
        while j < bytes.len() {
            out[pos] = bytes[j];
            pos += 1;
            j += 1;
        }
        i += 1;
    }
    assert!(pos == N, "`N` must be the total length of `parts`");
    out
}
